ZoneShape[] shapes;   // the zone's landmark terrain, live once PrepareShapes has levelled its pads
/// <summary>Levels each pad: the mean natural height round the ring where it meets the ground, plus its own height.</summary>
void PrepareShapes()
{
    if (Zone.shapes == null || Zone.shapes.Length == 0) return;
    foreach (var s in Zone.shapes)
    {
        if (s == null || s.kind == "step") continue;
        float r = s.radius + Mathf.Max(.5f, s.blend), sum = 0;
        for (int i = 0; i < 16; i++) { float a = i * Mathf.PI / 8; sum += HeightAt(s.center.x + Mathf.Cos(a) * r, s.center.y + Mathf.Sin(a) * r, false); }
        s.level = sum / 16 + s.height;
    }
    shapes = Zone.shapes;
}
/// <summary>Landmark terrain over the natural ground: pads, perches and basins level it, steps raise a scarp.</summary>
float Shape(float x, float z, float h)
{
    var p = new Vector2(x, z);
    foreach (var s in shapes)
    {
        if (s == null) continue;
        float blend = Mathf.Max(.5f, s.blend);
        if (s.kind == "step") { if (StepSide(s, p, out float side, out float fade) && side > 0) h += s.height * Mathf.SmoothStep(0, 1, side / blend) * fade; continue; }
        float d = Vector2.Distance(p, s.center) - s.radius;
        if (d < blend) h = Mathf.Lerp(h, s.level, 1 - Mathf.SmoothStep(0, 1, d / blend));
    }
    return h;
}
/// <summary>Where p lies against a step: side in metres (positive on the high side, right of first-to-last point) and fade (1 alongside it, 0 radius metres past its ends).</summary>
static bool StepSide(ZoneShape s, Vector2 p, out float side, out float fade)
{
    side = fade = 0; if (s.points == null || s.points.Length < 2) return false;
    Vector2 a = s.points[0], ab = s.points[1] - a; float len = ab.magnitude; if (len < .01f) return false;
    var d = ab / len; var rel = p - a; float along = Vector2.Dot(rel, d);
    side = d.y * rel.x - d.x * rel.y; fade = 1 - Mathf.SmoothStep(0, 1, (along < 0 ? -along : along - len) / Mathf.Max(1, s.radius));
    return true;
}
/// <summary>How much of a shape's ground paint covers p (0..1): a basin's floor, a perch's rim and slopes, a scarp's face and foot.</summary>
static float ShapeCover(ZoneShape s, Vector2 p)
{
    float blend = Mathf.Max(.5f, s.blend);
